// The salminis' shoal on the space page: little astronaut bots (species in salminis.js,
// generated by scripts/website/genspace.py) fly across the screen, flicker their jetpacks and flee
// from the pointer, faster the closer it comes. The boss only passes by now and then.
// Without this script, or unless the reader has no motion preference, space.css shows a
// still tile instead.
(function () {
  if (!window.matchMedia || !window.matchMedia("(prefers-reduced-motion: no-preference)").matches) return;
  var data = window.SALMINIS;
  if (!data || !document.createElementNS) return;
  var SVG = "http://www.w3.org/2000/svg";
  var BASE_W = 74, BASE_H = 52;

  function start() {
    var root = document.documentElement;
    root.classList.add("shoal-js");
    var layer = document.createElement("div");
    layer.className = "shoal";
    layer.setAttribute("aria-hidden", "true");
    document.body.insertBefore(layer, document.body.firstChild);

    var vw = window.innerWidth, vh = window.innerHeight;
    var fish = [];

    Object.keys(data.species).forEach(function (name) {
      var sp = data.species[name];
      for (var i = 0; i < sp.count; i++) {
        var svg = document.createElementNS(SVG, "svg");
        svg.setAttribute("viewBox", data.view);
        svg.setAttribute("class", "salmini salmini--" + name);
        svg.innerHTML = sp.svg;
        var w = BASE_W * sp.scale, h = BASE_H * sp.scale;
        svg.style.width = w + "px";
        svg.style.height = h + "px";
        svg.style.setProperty("--wag", sp.wag + "s");
        svg.style.opacity = name === "boss" ? 0.9 : (0.7 + Math.random() * 0.25).toFixed(2);
        layer.appendChild(svg);
        var f = {
          el: svg, name: name, w: w, h: h, speed: sp.speed * (0.85 + Math.random() * 0.3),
          x: Math.random() * vw, y: Math.random() * Math.max(1, vh - h),
          vx: 0, vy: 0, phase: Math.random() * Math.PI * 2, fleeing: false
        };
        f.vx = f.speed;
        if (name === "boss") f.x = -w - 600 - Math.random() * 600; // arrives after a while
        fish.push(f);
        place(f, 0);
      }
    });

    function place(f, tilt) {
      var facing = f.vx < 0 ? -1 : 1;
      f.el.style.transform = "translate(" + f.x.toFixed(1) + "px," + f.y.toFixed(1) + "px) rotate(" +
        (tilt * facing).toFixed(1) + "deg) scaleX(" + facing + ")";
    }

    window.addEventListener("resize", function () {
      vw = window.innerWidth;
      vh = window.innerHeight;
    });

    // The pointer, or a finger; far away when there is none.
    var px = -9999, py = -9999;
    function point(e) {
      px = e.clientX;
      py = e.clientY;
    }
    window.addEventListener("pointermove", point, { passive: true });
    window.addEventListener("pointerdown", point, { passive: true });
    document.addEventListener("pointerleave", function () { px = py = -9999; });
    window.addEventListener("blur", function () { px = py = -9999; });

    var last = null;
    function frame(t) {
      var dt = last === null ? 0 : Math.min(0.05, (t - last) / 1000);
      last = t;
      var time = t / 1000;
      fish.forEach(function (f) {
        // Cruise right, bobbing up and down.
        var tx = f.speed;
        var ty = Math.sin(time * 0.7 + f.phase) * f.speed * 0.35;
        // Flee: pushed away from the pointer, harder the closer it is.
        var cx = f.x + f.w / 2, cy = f.y + f.h / 2;
        var dx = cx - px, dy = cy - py;
        var d = Math.sqrt(dx * dx + dy * dy) || 1;
        var reach = 110 + f.w * 0.6;
        var fleeing = d < reach;
        if (fleeing) {
          var push = (1 - d / reach) * 2600 / Math.sqrt(f.w / 40);
          f.vx += (dx / d) * push * dt;
          f.vy += (dy / d) * push * dt;
        }
        if (fleeing !== f.fleeing) {
          f.fleeing = fleeing;
          f.el.classList.toggle("is-fleeing", fleeing);
        }
        // Calm down again, back to cruising.
        var calm = Math.min(1, dt * (fleeing ? 0.6 : 1.4));
        f.vx += (tx - f.vx) * calm;
        f.vy += (ty - f.vy) * calm;
        f.x += f.vx * dt;
        f.y += f.vy * dt;
        // Off the right edge: back in from the left at a new height (the boss after a pause).
        if (f.x > vw + 40) {
          f.x = -f.w - (f.name === "boss" ? 900 + Math.random() * 900 : 40 + Math.random() * 300);
          f.y = Math.random() * Math.max(1, vh - f.h);
        }
        if (f.x < -f.w - 2000) f.x = vw;             // fled far off to the left
        if (f.y < -f.h * 0.5) { f.y = -f.h * 0.5; f.vy = Math.abs(f.vy); }
        if (f.y > vh - f.h * 0.5) { f.y = vh - f.h * 0.5; f.vy = -Math.abs(f.vy); }
        var tilt = Math.max(-25, Math.min(25, Math.atan2(f.vy, Math.abs(f.vx) + 1) * 57.3));
        place(f, tilt);
      });
      requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", start);
  } else {
    start();
  }
})();
